import sys

def ncr(n, r):
    if r > n:
        return 0
    ans = 1
    for i in range(n, n - r, -1):
        ans *= i
    for i in range(2, r + 1):
        ans //= i
    return ans

def probab(n, x):
    a = ncr(x, 3) * ncr(n - x, 0)
    b = ncr(x, 2) * ncr(n - x, 1)
    c = ncr(x, 1) * ncr(n - x, 2)
    return ((3.0 / 6) * c + a + b) / ncr(n, 3)

def main():
    input_line = sys.stdin.readline().strip()
    s = input_line.split()
    n = int(s[0])
    p = float(s[1])
    for i in range(n + 1):
        if probab(n, i) >= p:
            print(i)
            break

if __name__ == "__main__":
    main()

